// Generates src/lib/chain/escrow-abi.ts from the Foundry build output.
// Usage: pnpm abi   (runs `forge build` in contracts/ first)
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const artifact = path.join(root, "contracts/out/FreelanceEscrow.sol/FreelanceEscrow.json");
const target = path.join(root, "src/lib/chain/escrow-abi.ts");

const { abi } = JSON.parse(readFileSync(artifact, "utf8"));
const body =
  "// GENERATED by `pnpm abi` from contracts/out/FreelanceEscrow.sol/FreelanceEscrow.json. Do not edit.\n" +
  `export const escrowAbi = ${JSON.stringify(abi, null, 2)} as const;\n`;
writeFileSync(target, body);
console.log(`wrote ${path.relative(root, target)} (${abi.length} entries)`);
